ControlPropertyState.AutoRuleBindingString:
// OnVisible 최상단에 조건문 추가
If(
    !varIsAddingReceipt, // 첨부 파일 추가 중이 아닐 때만(즉, 처음 진입 시에만) 초기화
    UpdateContext({ 
        locCurrentSetup: Blank(),
        dirtyTransAmount: Blank(),
        locIsEditingAmount: false,
        locCategoryChange: false,
        // 👇 [신규 추가] AirfareAllowance 모드가 아닐때만 무조건 이전 Purpose 메모리를 날려버림
        ctxTargetPurpose: If(varAppMode <> "AirfareAllowance", Blank(), ctxTargetPurpose),
        varViewOnly: false,
        varStateSelected: Blank(),
        varZipCodeSelectedRecId: -1,
        varProjectHierarchyId: Blank(),
        onReloadButtonClick: false,
        // LCY 계산 결과 저장 변수 초기화 (기존 값이 있으면 사용, 없으면 빈 값)
        // 1. 기존 LCY에 문자열로 저장된 값("100.00 USD")에서 공백(" ")을 기준으로 금액과 통화를 분리
        locOriginalAmount: If(
            !varIsCreate && !IsBlank(varSelectedExpenseDoc.LCY) && Find(" ", varSelectedExpenseDoc.LCY) > 0, 
            Left(varSelectedExpenseDoc.LCY, Find(" ", varSelectedExpenseDoc.LCY) - 1),
            Blank()
        ),
        locOriginalCurrency: If(
            !varIsCreate && !IsBlank(varSelectedExpenseDoc.LCY) && Find(" ", varSelectedExpenseDoc.LCY) > 0, 
            Right(varSelectedExpenseDoc.LCY, Len(varSelectedExpenseDoc.LCY) - Find(" ", varSelectedExpenseDoc.LCY)),
            Blank()
        ),
        // 2. locCalculatedLCY에는 Value() 오류 방지를 위해, 실제로 환산된 '숫자'인 Transaction amount(예: 137601)를 저장
        locCalculatedLCY: If(
            !varIsCreate, 
            Text(varSelectedExpenseDoc.'Transaction amount'), 
            Blank()
        )
    })
);
// 신규 경비 작성 모드 진입 시(영수증 추가를 위한 리프레시 상태가 아닐 때) 임시 영수증 비우기
If(
    varIsCreate && !varIsAddingReceipt,
    Clear(colPendingReceipts);
    Clear(colAttachedReceipts)
);


// 통화 데이터를 가져와서 미리 정렬한 뒤 'colSortedCurrencies'라는 컬렉션에 저장합니다.
ClearCollect(
    colCurrencies,
    'Currencies (mserp)'
);

ClearCollect(
    colSortedCurrencies,
    Sort(
        colCurrencies,
        If(
            IsBlank('Sort Order') Or 'Sort Order' = 0, 
            999999, 
            'Sort Order'
        ),
        SortOrder.Ascending
    )
);

// 환율 정보 조회
ClearCollect(colExchangeRates, 'Currency table (mserp)');

If(
    !varIsAddingReceipt, // 첨부 파일 추가 후 복귀한 상태가 아닐 때만 필드 초기화 실행

    // 3-level category selection variables
    UpdateContext({
        varSelectedExpenseType: 
        If(
            varIsCreate, 
            // 신규 생성 시 varAppMode에 따라 기본값 설정
            Switch(
                varAppMode,
                "ExpenseReport", "Expense Reimbursement",
                "AirfareAllowance", "Allowance",
                "BillingTripSettlement", "Billing Trip Settlement",
                "EmployeeBenefit", "Employee Benefit",
                Blank()
            ),
            // 수정 모드일 때는 초기화 (이후 로직에서 기존 값 매핑됨)
            Coalesce(varSelectedExpenseDoc.'Expense Type', Blank())
        )
    });

    // =========================================================================
    // 🚀 [여기에 Step 1 추가] : Purpose가 매핑 테이블에 존재하는지 실제 검증
    // =========================================================================
    UpdateContext({
        locMatchedMapping: If(
            varIsCreate && !IsBlank(ctxTargetPurpose),
            LookUp('DCSL Expense Category Mapping Setup Entity (mserp)', 'Item or Service' = ctxTargetPurpose),
            Blank()
        )
    });

    UpdateContext({
        // ctxTargetPurpose 값이 존재하고, 테이블 조회 결과도 빈 값이 아닐 때만 true (잠금 및 자동 주입)
        varForceLock: varIsCreate && !IsBlank(ctxTargetPurpose) && !IsBlank(locMatchedMapping)
    });
    // =========================================================================

    // 1. Reports에서 넘겨받은 Purpose(ctxTargetPurpose)를 Item or Service에 자동 할당
    UpdateContext({
        varSelectedItemOrService: If(
            // 👇 [전문가 팁: 여기도 수정 필요] 기존 조건에 varForceLock을 추가합니다.
            varForceLock, 
            ctxTargetPurpose,
            Coalesce(varSelectedExpenseDoc.'Item or Service', Blank())
        )
    });

    // 2. 자동 할당된 Item or Service와 Expense Type을 기반으로 Purchase Category 역추적 및 매핑
    UpdateContext({
        varSelectedPurchaseCategory: If(
            // 👇 [전문가 팁: 여기도 수정 필요] 기존 조건에 varForceLock을 추가합니다.
            varForceLock,
            Coalesce(
                LookUp(
                    'DCSL Expense Category Mapping Setup Entity (mserp)',
                    'Expense Type' = varSelectedExpenseType && 'Item or Service' = ctxTargetPurpose,
                    'Purchase Category'
                ),
                Blank()
            ),
            Coalesce(varSelectedExpenseDoc.'Purchase Category', Blank())
        )
    });
    UpdateContext({varSelectedPurchaseCategoryValue: ""});
    UpdateContext({
        curCategory: If(
            !varIsCreate && !IsBlank(varSelectedExpenseDoc.'Expense category (mserp_costtype)'),
            varSelectedExpenseDoc.'Expense category (mserp_costtype)',
            // 신규 생성 시: 매핑 엔티티에서 3가지 조건으로 올바른 카테고리 실시간 조회
            If(
                varIsCreate && !IsBlank(varSelectedExpenseType) && !IsBlank(varSelectedItemOrService),
                Coalesce(
                    LookUp(
                        'DCSL Expense Category Mapping Setup Entity (mserp)',
                        'Expense Type' = varSelectedExpenseType &&
                        'Purchase Category' = varSelectedPurchaseCategory &&
                        'Item or Service' = varSelectedItemOrService,
                        'Expense category'
                    ),
                    Blank()
                ),
                Blank()
            )
        )
    });
    // 3. Purchase Category가 자동 세팅되었으므로, 하위 4단계인 Expense Category 컬렉션(colExpenseCategories) 미리 로드
    If(
        varIsCreate && !IsBlank(varSelectedExpenseType) && !IsBlank(varSelectedPurchaseCategory),
        ClearCollect(
            colExpenseCategories,
            SortByColumns(
                Filter(
                    ForAll(
                        Filter(
                            'DCSL Expense Category Mapping Setup Entity (mserp)',
                            !IsBlank('Expense category') &&
                            'Expense Type' = varSelectedExpenseType &&
                            'Purchase Category' = varSelectedPurchaseCategory &&
                            (
                                (varAppMode = "AirfareAllowance" && Airfare = 'NoYes (mserp)'.Yes) ||
                                (varAppMode <> "AirfareAllowance" && Airfare = 'NoYes (mserp)'.No)
                            )
                        ) As MappingRecord,
                        LookUp(
                            'Expense category (mserp)',
                            'Expense category' = MappingRecord.'Expense category' &&
                            Inactive = 'NoYes (mserp)'.No
                        )
                    ),
                    !IsBlank('Expense category') // 빈 레코드 제거
                ),
                "mserp_expensecategory",
                SortOrder.Ascending
            )
        );

        // 4. 추가로 환율 및 고정금액 처리를 위한 현재 셋업(locCurrentSetup) 데이터 메모리 로드
        UpdateContext({
            locCurrentSetup: LookUp(
                'DCSL Expense Category Mapping Setup Entity (mserp)',
                'Expense Type' = varSelectedExpenseType && 
                'Purchase Category' = varSelectedPurchaseCategory && 
                'Item or Service' = varSelectedItemOrService
            )
        })
    );
    // Cost Center context
    UpdateContext({varSelectedCostCenter: Blank()});
    // TargetText context
    UpdateContext({TargetText: ""});
    If(
        !varIsCreate && !IsBlank(varSelectedExpenseDoc.CostCenter),
        UpdateContext({
            varSelectedCostCenter: LookUp(
                'DCSL HPRCostShareApproval Entity (mserp)',
                'Dimension value' = varSelectedExpenseDoc.CostCenter
            )
        })
    );
    // Project context
    UpdateContext({varSelectedProject: Blank()});
    // Project type context (will be derived from Expense Type / Purchase Category / Item or Service)
    UpdateContext({varSelectedProjectType: Blank()});
    If(
        !varIsCreate && !IsBlank(varSelectedExpenseDoc.Project),
        UpdateContext({
            varSelectedProject: LookUp(
                Filter(
                    'DCSL Financial Dimension Master (mserp)',
                    'Dimension name' = "Project"
                ),
                'Dimension value' = varSelectedExpenseDoc.Project
            )
        })
    );
);
// Load existing Department and Benefit Type from Expense Category (reverse lookup)
// [수정됨] 이미 Dataverse에서 올바른 3단계 카테고리 값(Expense Type, Purchase Category 등)을
// 성공적으로 불러왔다면, 부정확한 Reverse Lookup으로 덮어쓰지 않도록 방어 로직 추가
If(
    !varIsCreate && 
    !IsBlank(varSelectedExpenseDoc.'Expense Type') &&
    (IsBlank(varSelectedExpenseType) || IsBlank(varSelectedPurchaseCategory) || IsBlank(varSelectedItemOrService)),

    With(
        {
            mappingRecord: LookUp(
                'DCSL Expense Category Mapping Setup Entity (mserp)',
                'Expense Type' = varSelectedExpenseDoc.'Expense Type' &&
                'Purchase Category' = varSelectedExpenseDoc.'Purchase Category' &&
                'Item or Service' = varSelectedExpenseDoc.'Item or Service'
            )
        },
        If(
            !IsBlank(mappingRecord),
            UpdateContext({
                varSelectedExpenseType: mappingRecord.'Expense Type'
            });
            UpdateContext({
                varSelectedPurchaseCategory: mappingRecord.'Purchase Category'
            });
            UpdateContext({
                varSelectedItemOrService: mappingRecord.'Item or Service'
            })
        )
    )
);

