UpdateContext({varLoadingSpinner : true});
If(
    !varIsCreate && 
    !IsBlank(varSelectedExpenseDoc.'Expense category (mserp_costtype)') &&
    varSelectedExpenseDoc.'Expense category (mserp_costtype)' <> "",
    UpdateContext(
        {
            locItemizeButtonVisibilityFlag : 'Expense mobile master data (mserp)'.mserp_trvexpmobilemasterdataentity_isexpenseitemizable(LookUp('Expense mobile master data (mserp)',Email = User().Email).'Expense mobile master data (mserp)', 
            {
                CostType: varSelectedExpenseDoc.'Expense category (mserp_costtype)',
                SplitLineType:"Default",
                LineType: If(varSelectedExpenseDoc.'Expense line type' = 'Expense line type (mserp)'.'Itemized header',"ItemizedHeader","Default")
            }).return

        }
    ),
    UpdateContext({locItemizeButtonVisibilityFlag: false})
);
If(
    !varIsCreate && gblIsProjectValidationFlag,
    Clear(colGetProjectsBasedOnResourceCategory);
    UpdateContext({
        varGetProjectsJson :
        IfError(
            Text(
                'Projects (mserp)'.mserp_trvexpmobileprojentity_getprojectsbasedonresourcecategory(LookUp('Expense mobile master data (mserp)',Email = User().Email).'Expense mobile master data (mserp)',
                    {
                        employeeLegalEntity: varSelectedLegalEntity,
                        interCompanyLegalEntity: curIntercompanyLE,
                        categoryId: 
                        If(
                            IsBlank(If(Upper(varSelectedLegalEntity) <> Upper(curIntercompanyLE), varSelectedExpenseDoc.'Intercompany project category', curCategory)),
                            "",
                            If(Upper(varSelectedLegalEntity) <> Upper(curIntercompanyLE), varSelectedExpenseDoc.'Intercompany project category', curCategory)
                        )
                    }).return
            ),
            ""
        )
    });
    If(
        !IsBlank(varGetProjectsJson),
        ClearCollect(
            colGetProjectsBasedOnResourceCategory,
            ForAll(
                MatchAll(varGetProjectsJson, "\{""projId"":""(?<projId>[^""]*)"",""projName"":""(?<projName>[^""]*)""\}") As ProjectListFromCol,
                {
                    projectId: ProjectListFromCol.projId, 
                    projectName: ProjectListFromCol.projName
                }
            )
        ),
        Clear(colGetProjectsBasedOnResourceCategory)
    );

    If(
        !IsBlankOrError(curProjIdSelected),
        UpdateContext({
            varProjectHierarchyId:
                LookUp(
                    'Projects (mserp)',
                    'Project ID' = curProjIdSelected,
                    HierarchyId
                )
        })
    );
);
UpdateContext({locItemizationCheck : locItemizeButtonVisibilityFlag});
UpdateContext(
    {
        timerCostType: false,
        timerProj: false,
        timerHBIT: false,
        timerCountry: false,
        timerState: false,
        locAllowNavigationBack: true
    }
);
// populate the current expense type of the selected document
UpdateContext(
    {
        currExpenseType: Coalesce(
            varSelectedExpenseDoc.'Expense type',
            If(
                !IsBlank(varSelectedExpenseDoc.'Expense category (mserp_costtype)'),
                LookUp(
                    'Expense category (mserp)',
                    'Expense category' = varSelectedExpenseDoc.'Expense category (mserp_costtype)',
                    'Expense type'
                ),
                Blank()
            )
        )
    }
);
If(
    !varIsCreate,
    UpdateContext({msCallStartedForSalestaxCalculation: true});
    UpdateContext({varOnShowFields: false});
    UpdateContext({varOnSelectTriggered: false});
    UpdateContext({varOnChangeTriggered: false});

);
UpdateContext(
    {
        featureEnabled: If(
            userRecord.IsReimaginedUIEnabled = 'NoYes (mserp)'.Yes,
            "True",
            "False"
        ),
        perdiemFeatureEnabled: If(
            userRecord.IsReImaginedPerDiemEnabled = 'NoYes (mserp)'.Yes,  //this needs to be changed to the perdiem feature enabled
            "True",
            "False"
        )
    }
);
//Check if the itemization is over or under distributed
If(
    !varIsCreate,
    If(
        varRemainingAmount < 0,
        Notify(
            GlobalLabels.Labels.'15062:LocalizedName,msdyn_ThisExpenseIsOverItemizedLabel',
            NotificationType.Error,
            gblParams.notificationTime
        ),
        varRemainingAmount > 0,
        Notify(GlobalLabels.Labels.'15062:LocalizedName,msdyn_ThisExpenseIsNotCompletelyItemizedLabel',
            NotificationType.Warning,
            gblParams.notificationTime
        )
    )
);
