    currExpenseType = 'TrvExpType (mserp)'.'Per diem' && (featureEnabled = "False" || perdiemFeatureEnabled = "False"),
    Notify(
        GlobalLabels.Labels.'15062:LocalizedName,msdyn_PerdiemFeatureDisabledWarning',
        //"Enable both re-imagined features to be able to edit this expense",
        NotificationType.Warning,
        gblParams.notificationTime
    )
);
//if labelTableLookUp not empty
If(
    CountRows(labelTableLookUp) <= 0,
    Collect(
        labelTableLookUp,
        {
            fieldName: "CostType",
            labelName: "Expense category",
            localisedLabelName: GlobalLabels.Labels.'15062:LocalizedName,msdyn_ExpenseCategoryLabel',
            visible: true,
            required: true
        },
        {
            fieldName: "TransDate",
            labelName: "Transaction date",
            localisedLabelName: GlobalLabels.Labels.'15062:LocalizedName,msdyn_TransactionDateLabel',
            visible: true,
            required: true
        },
        {
