            labelName: "Transaction amount",
            localisedLabelName: GlobalLabels.Labels.'15062:LocalizedName,msdyn_TransactionAmountLabel',
            visible: true,
            required: true
        },
        {
            fieldName: "ExchangeCode",
            labelName: "Currency",
            localisedLabelName: GlobalLabels.Labels.'15062:LocalizedName,msdyn_CurrencyLabel',
            visible: true,
            required: true
        },
        {
            fieldName: "PayMethod",
            labelName: "Payment method",
            localisedLabelName: GlobalLabels.Labels.'15062:LocalizedName,msdyn_PaymentMethodLabel',
            visible: true,
            required: true
        },
        {
            fieldName: "SubmitterJustification",
            labelName: "Employee justification",
            localisedLabelName: GlobalLabels.Labels.'15062:LocalizedName,msdyn_EmployeeJustificationLabel',
            visible: false,
            required: false
        }
    );
    ForAll(
        Filter(
            '@ExpenseManagement:ExpenseMobileFieldVisibilityEntity (mserp)',
            LegalEntityId = varSelectedLegalEntity
        ) As VisibilityTable,
        Collect(
            labelTableLookUp,
            {
                fieldName: VisibilityTable.FieldName,
                labelName: VisibilityTable.Labels,
                localisedLabelName: VisibilityTable.LocalisedLabelName
            }
        )
    );
    If(
        featureEnabled = "True",
        ForAll(
            Filter(
                '@ExpenseManagement:ExpenseMobileFieldVisibilityEntity (mserp)',
                LegalEntityId = varSelectedLegalEntity
            ) As VisibilityTable,
            Patch(
                labelTableLookUp,
                LookUp(
                    labelTableLookUp,
                    fieldName = VisibilityTable.FieldName
                ),
                {
                    visible: VisibilityTable.VisibilityType <> 'ExpenseFieldVisibilityType (mserp)'.'Do not display',
                    required: VisibilityTable.VisibilityType = 'ExpenseFieldVisibilityType (mserp)'.Required
                }
            )
        ),
        ForAll(
            Filter(
                'Display fields (mserp)',
                'Company Code' = varSelectedLegalEntity
            ) As VisibilityTable,
            Patch(
                labelTableLookUp,
                LookUp(
                    labelTableLookUp,
                    fieldName = VisibilityTable.FieldName
                ),
                {
                    visible: VisibilityTable.Visibility <> 'Visibility (mserp)'.'Do not display',
                    required: false
                }
            )
        )
    )
);
