// 복사 팝업창 가시성 제어 변수
UpdateContext({ locShowCopyPopup: false });

// 1. 접속한 사용자의 마스터 정보 가져오기 (화면에 '본인' 이름을 표시하기 위함)
Set(
    varCurrentD365User,
    LookUp('Expense mobile master data (mserp)', Email = User().Email)
);

// 2. [변경됨] 가상 필드 대신, 물리적 텍스트 필드(mserp_delegateduser)로 서버에서 직접 필터링합니다.
ClearCollect(
    colActiveDelegations,
    Filter(
        '@DEEX:DEEX_20316 (mserp)',
        // 텍스트 ID 끼리 비교합니다. (varCurrentD365User.mserp_userid 가 "DEEX1.ERP" 형태)
        Delegate = varCurrentD365User.ID && 
        'Start date' <= Today() &&
        'End date' >= Today()
    )
);

// 3. 콤보박스 선택지 생성 (첫 번째: 접속자 본인)
ClearCollect(
    colCreatingWorkerOptions,
    {
        WorkerID: userRecord.CreatingWorker, // 저장용 내 숫자 ID
        WorkerName: varCurrentD365User.ID & " (MySelf)" // 화면 표시용 내 이름
    }
);

// 4. 콤보박스 선택지 추가 (대리 신청 대상자)
ForAll(
    colActiveDelegations,
    Collect(
        colCreatingWorkerOptions,
        {
