Set(varSelectedReceiptNumber, Blank()); // [추가] 초기화
// 기존 Navigate 코드에 컨텍스트 변수 추가
UpdateContext({ varIsAddingReceipt: true });
Navigate('Expenses - Capture Receipt Screen', ScreenTransition.None);
UpdateContext(
    {
        varOnSelectTriggered: false,
        varOnShowFields:false,
        varOnChangeTriggered:false
    }
)

//GlobalLabels.Labels.'15062:LocalizedName,msdyn_AddReceiptLabel'
If(
    varAppMode = "AirfareAllowance",
    "Add Boarding pass, Itinerary, Receipt",
    "Add Receipt"
)

Navigate('Expenses - View Receipt Screen', ScreenTransition.None, {varViewOnly : false});
UpdateContext(
    {
        varOnSelectTriggered: false,
        varOnShowFields:false,
        varOnChangeTriggered:false
    }
)

// 1. 타이머를 다시 끌 수 있도록 변수 초기화
UpdateContext({ varStartAttachTimer: false });

// 2. 최종 연결 액션 수행 및 성공 여부 확인
UpdateContext({
    varLinkSuccess: IfError(
        'DCSL Apps Action Entity (mserp)'.mserp_linkdocureftoexpenseline({
            _expTransNumber: varTargetExpTransNumber,
            _docuRefRecId: locNewReturnedIds.return
        });
        true,  // 에러 없이 성공하면 true 반환
        false  // 에러가 발생하면 false 반환
    )
});

// 3. 성공/실패에 따른 분기 처리
If(
    varLinkSuccess,

    // [성공 시 로직] 
    // 💡 공통 후속 처리 숨김 버튼을 실행하여 안전하게 리스트 갱신, 컬렉션 삭제 및 화면 이동을 진행합니다.
    Select(scr030_btn_ExecutePostSubmit)
    ,

    // [실패 시 로직]
    // ❌ Clear(colPendingReceipts) 및 화면 이동을 절대 수행하지 않습니다!
    // 사용자가 현재 화면에서 다시 'Save' 버튼을 누를 수 있도록 로딩 표시(스피너)만 걷어내고 에러를 알립니다.
    UpdateContext({varLoadingSpinner: false});
    Notify("The attachment connection failed due to system delay. Please press the 'Save' button again.", NotificationType.Error, 5000)
)
